\begin{split}
	P(Y | X) &= P(Y | \mathbf{x_1, x_2, x_3, ..., x_{M}}) \\
	&= \prod_{i=1}^{N}P(y_i | y_0, y_1, y_2, ..., y_{i-1}; \mathbf{x_1, x_2, x_3, ..., x_{M}})
	\end{split}

\begin{split}
	s_t &= AttentionFunction(\mathbf{y}_{i-1}, \mathbf{x}_{t}) \quad  \forall t,   \quad  1 \leq t \leq M \\
	p_t &= \exp(s_t) / \sum_{t=1}^{M}\exp(s_t) \quad  \quad \forall t, \quad 1 \leq t \leq M \\
	\mathbf{a}_i &= \sum_{t=1}^{M} p_t . \mathbf{x}_t
	\end{split}

\begin{split}
	s(Y, X) &= \log(P(Y | X)) / lp(Y) + cp(X;Y) \\
	lp(Y) &= \frac{(5 + |Y|) ^ \alpha}{(5 + 1) ^ \alpha} \\
	cp(X;Y) &= \beta * \sum_{i=1}^{|X|}{\log(\min(\sum_{j=1}^{|Y|}{p_{i, j}}, 1.0))},
	\end{split}
